BOOK.add({
  subject: "math",
  id: "math-13",
  title: "रेखा तथा कोण — रेखाखंड, सरल एवं वक्र रेखाएँ, कोणों के प्रकार",
  notes: "\n    <h3>1. ज्यामिति की मूल इकाइयाँ — बिंदु, रेखा, किरण, रेखाखंड</h3>\n    <p><b>बिंदु (Point):</b> केवल स्थिति बताता है; इसकी कोई लंबाई, चौड़ाई या मोटाई नहीं होती। इसे बड़े अक्षर (A, B, P) से दर्शाते हैं।</p>\n    <p><b>रेखा (Line):</b> दोनों दिशाओं में अनंत तक फैली सीधी आकृति। इसका कोई अंत बिंदु नहीं होता, इसलिए इसकी लंबाई मापी नहीं जा सकती। संकेत: रेखा AB या रेखा l।</p>\n    <p><b>किरण (Ray):</b> एक प्रारंभिक बिंदु से शुरू होकर एक ही दिशा में अनंत तक जाती है। इसका केवल <b>एक</b> अंत बिंदु होता है। उदाहरण — टॉर्च या सूर्य से निकला प्रकाश। किरण AB और किरण BA अलग-अलग हैं (प्रारंभ बिंदु अलग)।</p>\n    <p><b>रेखाखंड (Line Segment):</b> रेखा का वह भाग जिसके <b>दो</b> अंत बिंदु हों। इसकी निश्चित लंबाई होती है, जिसे मापा जा सकता है। रेखाखंड AB = रेखाखंड BA।</p>\n    <table>\n      <tr><th>आकृति</th><th>अंत बिंदु</th><th>लंबाई</th><th>उदाहरण</th></tr>\n      <tr><td>रेखा</td><td>0</td><td>अनंत (माप नहीं सकते)</td><td>दोनों ओर तीर वाली सीधी रेखा</td></tr>\n      <tr><td>किरण</td><td>1</td><td>अनंत (माप नहीं सकते)</td><td>सूर्य/टॉर्च का प्रकाश</td></tr>\n      <tr><td>रेखाखंड</td><td>2</td><td>निश्चित (माप सकते हैं)</td><td>स्केल का किनारा, पेंसिल</td></tr>\n    </table>\n    <h4>महत्त्वपूर्ण अभिगृहीत (NCERT)</h4>\n    <ul>\n      <li>एक बिंदु से होकर <b>अनगिनत (अनंत)</b> रेखाएँ खींची जा सकती हैं।</li>\n      <li>दो भिन्न बिंदुओं से होकर <b>एक और केवल एक</b> रेखा खींची जा सकती है।</li>\n      <li>दो भिन्न रेखाएँ अधिकतम <b>एक</b> बिंदु पर प्रतिच्छेद करती हैं।</li>\n      <li>एक बिंदु से होकर दी गई रेखा के समांतर केवल एक रेखा खींची जा सकती है (प्लेफेयर अभिगृहीत)।</li>\n    </ul>\n\n    <h3>2. सरल रेखा और वक्र रेखा</h3>\n    <ul>\n      <li><b>सरल (सीधी) रेखा:</b> जिसकी दिशा कहीं नहीं बदलती।</li>\n      <li><b>वक्र रेखा:</b> जिसकी दिशा लगातार बदलती है, जैसे वृत्त, चाप, लहर।</li>\n      <li><b>सरल वक्र:</b> जो स्वयं को कहीं नहीं काटता। <b>बंद वक्र:</b> जिसके दोनों सिरे मिल जाएँ (जैसे O, वृत्त)। <b>खुला वक्र:</b> सिरे न मिलें (जैसे C, U)।</li>\n      <li>अक्षर O, D = सरल बंद वक्र; अंक 8 = बंद पर सरल नहीं (स्वयं को काटता है)।</li>\n    </ul>\n\n    <h3>3. रेखाओं के संबंध</h3>\n    <table>\n      <tr><th>शब्द</th><th>अर्थ</th></tr>\n      <tr><td>संरेख बिंदु (Collinear)</td><td>तीन या अधिक बिंदु जो एक ही रेखा पर हों</td></tr>\n      <tr><td>असंरेख बिंदु</td><td>जो एक रेखा पर न हों (तीन असंरेख बिंदु एक त्रिभुज बनाते हैं)</td></tr>\n      <tr><td>प्रतिच्छेदी रेखाएँ</td><td>जो एक बिंदु पर काटें (उभयनिष्ठ बिंदु = प्रतिच्छेद बिंदु)</td></tr>\n      <tr><td>समांतर रेखाएँ</td><td>एक ही तल में, कभी न मिलें; उनके बीच की लंबवत दूरी सर्वत्र समान</td></tr>\n      <tr><td>संगामी रेखाएँ (Concurrent)</td><td>तीन या अधिक रेखाएँ जो एक ही बिंदु से गुजरें</td></tr>\n      <tr><td>लंबवत रेखाएँ</td><td>जो परस्पर 90° पर काटें (संकेत ⊥)</td></tr>\n      <tr><td>तिर्यक रेखा (Transversal)</td><td>जो दो या अधिक रेखाओं को भिन्न-भिन्न बिंदुओं पर काटे</td></tr>\n    </table>\n\n    <h3>4. बिंदुओं और रेखाओं की गिनती के सूत्र</h3>\n    <ul>\n      <li>n बिंदु, जिनमें कोई तीन संरेख नहीं: रेखाओं की संख्या = <b>n(n−1)/2</b></li>\n      <li>इन्हीं से बनने वाले त्रिभुज = <b>n(n−1)(n−2)/6</b></li>\n      <li>n बिंदुओं में से m बिंदु संरेख हों (शेष में कोई तीन संरेख नहीं): रेखाएँ = n(n−1)/2 − m(m−1)/2 + 1</li>\n      <li>n रेखाएँ, जिनमें कोई दो समांतर नहीं और कोई तीन संगामी नहीं: प्रतिच्छेद बिंदु = <b>n(n−1)/2</b></li>\n    </ul>\n    <div class=\"tip\">हल उदाहरण 1: 8 बिंदु (कोई तीन संरेख नहीं) → रेखाएँ = 8×7/2 = 28, त्रिभुज = 8×7×6/6 = 56।<br>हल उदाहरण 2: 10 बिंदु जिनमें 4 संरेख → 45 − 6 + 1 = 40 रेखाएँ। (4 संरेख बिंदुओं से 6 अलग रेखाएँ नहीं, केवल 1 रेखा बनती है।)</div>\n\n    <h3>5. कोण और उसके प्रकार</h3>\n    <p>एक ही प्रारंभिक बिंदु वाली दो किरणों से कोण बनता है। उभयनिष्ठ बिंदु = <b>शीर्ष</b>, किरणें = <b>भुजाएँ</b>। ∠ABC में शीर्ष B है (बीच वाला अक्षर)।</p>\n    <table>\n      <tr><th>कोण</th><th>माप</th><th>उदाहरण</th></tr>\n      <tr><td>शून्य कोण</td><td>0°</td><td>दोनों भुजाएँ संपाती</td></tr>\n      <tr><td>न्यून कोण (Acute)</td><td>0° से अधिक, 90° से कम</td><td>30°, 75°, 89°</td></tr>\n      <tr><td>समकोण (Right)</td><td>ठीक 90°</td><td>कमरे का कोना</td></tr>\n      <tr><td>अधिक कोण (Obtuse)</td><td>90° से अधिक, 180° से कम</td><td>91°, 135°, 170°</td></tr>\n      <tr><td>सरल / ऋजु कोण (Straight)</td><td>ठीक 180°</td><td>सीधी रेखा</td></tr>\n      <tr><td>प्रतिवर्ती / वृहत् कोण (Reflex)</td><td>180° से अधिक, 360° से कम</td><td>200°, 300°</td></tr>\n      <tr><td>संपूर्ण कोण (Complete)</td><td>ठीक 360°</td><td>एक पूरा चक्कर</td></tr>\n    </table>\n    <p>किसी कोण θ का <b>प्रतिवर्ती कोण</b> = 360° − θ। जैसे 110° का प्रतिवर्ती = 250°।</p>\n\n    <h3>6. कोण-युग्म</h3>\n    <ul>\n      <li><b>पूरक कोण (Complementary):</b> योग 90°। θ का पूरक = 90° − θ।</li>\n      <li><b>संपूरक कोण (Supplementary):</b> योग 180°। θ का संपूरक = 180° − θ।</li>\n      <li>संपूरक − पूरक = सदा 90° (क्योंकि (180−θ) − (90−θ) = 90)।</li>\n      <li><b>आसन्न कोण (Adjacent):</b> उभयनिष्ठ शीर्ष, एक उभयनिष्ठ भुजा, और अउभयनिष्ठ भुजाएँ उभयनिष्ठ भुजा के विपरीत ओर।</li>\n      <li><b>रैखिक युग्म (Linear Pair):</b> ऐसे आसन्न कोण जिनकी अउभयनिष्ठ भुजाएँ एक सीधी रेखा बनाती हैं — योग 180°। (हर रैखिक युग्म संपूरक होता है, पर हर संपूरक युग्म रैखिक युग्म नहीं।)</li>\n      <li><b>शीर्षाभिमुख कोण (Vertically Opposite):</b> दो रेखाएँ काटें तो आमने-सामने के कोण — सदा <b>बराबर</b>।</li>\n      <li>एक बिंदु के चारों ओर सभी कोणों का योग = 360°।</li>\n    </ul>\n    <div class=\"tip\">हल उदाहरण 3: \"एक कोण अपने पूरक का दोगुना है।\" मान लें कोण x → x = 2(90 − x) → 3x = 180 → x = 60°।<br>हल उदाहरण 4: \"एक कोण का संपूरक उसके पूरक का 4 गुना है।\" 180 − x = 4(90 − x) → 3x = 180 → x = 60°।<br>हल उदाहरण 5: \"दो संपूरक कोणों का अनुपात 4 : 5\" → 180 × 4/9 = 80°, 180 × 5/9 = 100°।</div>\n\n    <h3>7. समांतर रेखाएँ और तिर्यक रेखा</h3>\n    <p>दो रेखाओं l और m को तिर्यक रेखा t काटे तो कुल <b>8 कोण</b> बनते हैं — 4 अंतः कोण (दोनों रेखाओं के बीच) और 4 बाह्य कोण।</p>\n    <table>\n      <tr><th>कोण-युग्म</th><th>पहचान</th><th>l ∥ m होने पर</th></tr>\n      <tr><td>संगत कोण (Corresponding)</td><td>तिर्यक रेखा के एक ही ओर, प्रत्येक रेखा पर एक ही स्थिति में</td><td>बराबर</td></tr>\n      <tr><td>एकांतर अंतः कोण (Alternate Interior)</td><td>दोनों रेखाओं के बीच, तिर्यक रेखा के विपरीत ओर (Z आकृति)</td><td>बराबर</td></tr>\n      <tr><td>एकांतर बाह्य कोण</td><td>बाहर की ओर, तिर्यक रेखा के विपरीत ओर</td><td>बराबर</td></tr>\n      <tr><td>तिर्यक रेखा के एक ही ओर के अंतः कोण (Co-interior / सह-अंतः)</td><td>बीच में, एक ही ओर (C या U आकृति)</td><td>योग 180° (संपूरक)</td></tr>\n    </table>\n    <ul>\n      <li>विलोम भी सत्य है — यदि संगत कोण बराबर हों, या एकांतर कोण बराबर हों, या एक ही ओर के अंतः कोणों का योग 180° हो, तो रेखाएँ <b>समांतर</b> होती हैं।</li>\n      <li>समांतर रेखाओं पर तिर्यक रेखा से बने 8 कोणों में अधिकतम <b>दो भिन्न माप</b> होते हैं: x और 180° − x।</li>\n      <li>यदि तिर्यक रेखा एक समांतर रेखा पर लंब है तो दूसरी पर भी लंब होगी।</li>\n      <li>एक ही रेखा के समांतर दो रेखाएँ परस्पर समांतर होती हैं।</li>\n    </ul>\n    <div class=\"tip\">हल उदाहरण 6: समांतर रेखाओं पर एक ही ओर के अंतः कोण (2x + 10)° और (3x − 5)° हैं → 5x + 5 = 180 → x = 35 → कोण 80° और 100°।</div>\n\n    <h3>8. कोण समद्विभाजक</h3>\n    <ul>\n      <li>वह किरण जो कोण को दो बराबर भागों में बाँटे। समद्विभाजक पर स्थित प्रत्येक बिंदु कोण की दोनों भुजाओं से समान दूरी पर होता है।</li>\n      <li>रैखिक युग्म के दोनों कोणों के समद्विभाजकों के बीच कोण = 180/2 = <b>90°</b>।</li>\n      <li>दो आसन्न पूरक कोणों के समद्विभाजकों के बीच कोण = 90/2 = <b>45°</b>।</li>\n      <li>शीर्षाभिमुख कोणों के समद्विभाजक एक ही सीधी रेखा में होते हैं।</li>\n    </ul>\n\n    <h3>9. घड़ी के कोण — एक झलक</h3>\n    <table>\n      <tr><th>सुई</th><th>प्रति घंटा</th><th>प्रति मिनट</th><th>प्रति सेकंड</th></tr>\n      <tr><td>घंटे की सुई</td><td>30°</td><td>1/2° = 0.5°</td><td>1/120°</td></tr>\n      <tr><td>मिनट की सुई</td><td>360°</td><td>6°</td><td>1/10° = 0.1°</td></tr>\n      <tr><td>सेकंड की सुई</td><td>360 × 60°</td><td>360°</td><td>6°</td></tr>\n    </table>\n    <p>मिनट की सुई, घंटे की सुई से प्रति मिनट 6 − 0.5 = <b>5.5° (11/2°)</b> अधिक घूमती है। घड़ी के दो अंकों के बीच (5 मिनट के खाने) = 30°।</p>\n    <p><b>सूत्र:</b> H घंटे M मिनट पर दोनों सुइयों के बीच कोण <b>θ = |30H − 5.5M|</b>। यदि θ &gt; 180° आए तो छोटा कोण = 360° − θ।</p>\n    <div class=\"tip\">हल उदाहरण 7: 3:40 पर → |30×3 − 5.5×40| = |90 − 220| = 130°।<br>हल उदाहरण 8: 9:15 पर → |270 − 82.5| = 187.5° → छोटा कोण = 360 − 187.5 = 172.5°।<br>हल उदाहरण 9: 3 और 4 के बीच सुइयाँ कब मिलेंगी? 30×3 = 5.5M → M = 90 × 2/11 = 180/11 = 16 4/11 मिनट।</div>\n    <ul>\n      <li>12 घंटे में सुइयाँ 11 बार संपाती (मिलती) हैं, 24 घंटे में 22 बार।</li>\n      <li>12 घंटे में 22 बार समकोण बनाती हैं, 24 घंटे में 44 बार।</li>\n      <li>12 घंटे में 11 बार विपरीत (180°) होती हैं, 24 घंटे में 22 बार।</li>\n      <li>सही घड़ी में सुइयाँ हर 65 5/11 मिनट बाद मिलती हैं।</li>\n    </ul>\n\n    <h3>10. कोण मापन — डिग्री, मिनट, सेकंड तथा रेडियन</h3>\n    <ul>\n      <li>1 संपूर्ण चक्कर = 360°; 1° = 60′ (मिनट); 1′ = 60″ (सेकंड); अतः 1° = 3600″।</li>\n      <li>दशमलव से बदलना: 25.5° = 25° + 0.5 × 60′ = 25°30′; 40.25° = 40°15′।</li>\n      <li>जोड़-घटाव में 60′ होते ही 1° बना दें: 45°30′ + 30°45′ = 75°75′ = 76°15′।</li>\n      <li><b>रेडियन:</b> वृत्त की त्रिज्या के बराबर चाप केन्द्र पर जो कोण बनाता है वह 1 रेडियन है। π रेडियन = 180°।</li>\n      <li>डिग्री → रेडियन: × π/180; रेडियन → डिग्री: × 180/π।</li>\n      <li>1 रेडियन ≈ 57°16′ (लगभग 57.3°); 1° ≈ 0.01745 रेडियन।</li>\n    </ul>\n    <table>\n      <tr><th>डिग्री</th><th>30°</th><th>45°</th><th>60°</th><th>90°</th><th>120°</th><th>135°</th><th>150°</th><th>180°</th><th>270°</th><th>360°</th></tr>\n      <tr><td>रेडियन</td><td>π/6</td><td>π/4</td><td>π/3</td><td>π/2</td><td>2π/3</td><td>3π/4</td><td>5π/6</td><td>π</td><td>3π/2</td><td>2π</td></tr>\n    </table>\n    <div class=\"tip\">याद रखें: \"पूरक = 90 (P से पहले आता है, छोटा), संपूरक = 180 (सं जुड़ा, बड़ा)।\" रैखिक युग्म = सीधी रेखा = 180°; शीर्षाभिमुख = आमने-सामने = बराबर।</div>\n  ",
  extra: "\n    <h3>शॉर्टकट व गहन ट्रिक्स</h3>\n    <h4>1. पूरक/संपूरक शब्द-प्रश्नों का एक-पंक्ति सूत्र</h4>\n    <ul>\n      <li>\"कोण अपने पूरक का k गुना है\" → कोण = 90k/(k+1)। k = 2 → 60°, k = 5 → 75°।</li>\n      <li>\"कोण अपने संपूरक का k गुना है\" → कोण = 180k/(k+1)। k = 1/4 → 36°, k = 2 → 120°।</li>\n      <li>\"कोण अपने पूरक से d अधिक है\" → कोण = (90 + d)/2। \"संपूरक से d अधिक\" → (180 + d)/2।</li>\n      <li>\"संपूरक, पूरक का k गुना है\" → 180 − x = k(90 − x) → x = 90(k − 2)/(k − 1)। k = 4 → 60°, k = 3 → 45°।</li>\n      <li>\"पूरक + संपूरक = S\" → 270 − 2x = S → x = (270 − S)/2।</li>\n      <li>\"कोण अपने प्रतिवर्ती कोण का 1/k है\" → x = 360/(k + 1)।</li>\n    </ul>\n    <h4>2. घड़ी के गहन सूत्र</h4>\n    <ul>\n      <li>H और (H+1) के बीच सुइयाँ मिलें: M = (60H)/11 = 5H × 12/11 मिनट।</li>\n      <li>H और (H+1) के बीच θ कोण: M = (2/11)(30H ± θ) — दोनों चिह्न आज़माएँ, जो 0 से 60 के बीच आए वही मान्य।</li>\n      <li>विपरीत (180°) स्थिति: M = (2/11)(30H ± 180)।</li>\n      <li>12 घंटे में 24 के बजाय 22 समकोण क्यों? 2 से 4 बजे के बीच केवल 3 समकोण बनते हैं (3:00 वाला समकोण दोनों घंटों में साझा) और 8 से 10 बजे के बीच भी केवल 3 (9:00 साझा) — इस प्रकार 2 कम।</li>\n      <li>6:00 और 12:00 दोनों विशेष: 12:00 पर संपाती, 6:00 पर विपरीत। 11 और 1 बजे के बीच केवल एक बार (12:00) मिलती हैं।</li>\n      <li>घंटे की सुई का कोण (12 से) = 30H + 0.5M; मिनट की सुई का = 6M। अंतर ही सूत्र |30H − 5.5M| है।</li>\n    </ul>\n    <h4>3. रेखाओं/बिंदुओं की गिनती</h4>\n    <ul>\n      <li>त्वरित तालिका n(n−1)/2: 4→6, 5→10, 6→15, 7→21, 8→28, 9→36, 10→45, 12→66, 15→105, 20→190।</li>\n      <li>उल्टा प्रश्न \"कितने बिंदु से 45 रेखाएँ?\" → दो क्रमागत संख्याओं का गुणनफल 90 = 10 × 9 → n = 10।</li>\n      <li>संरेख बिंदुओं वाला सुधार: m संरेख बिंदुओं की m(m−1)/2 रेखाएँ घटाओ और 1 जोड़ो। त्रिभुजों में केवल m(m−1)(m−2)/6 घटाओ (कुछ जोड़ना नहीं)।</li>\n    </ul>\n    <h4>4. समांतर रेखाओं की त्वरित पहचान</h4>\n    <ul>\n      <li><b>F आकृति</b> = संगत कोण (बराबर), <b>Z आकृति</b> = एकांतर कोण (बराबर), <b>C/U आकृति</b> = सह-अंतः कोण (योग 180°)।</li>\n      <li>\"पैर में कोण\" (दो समांतर रेखाओं के बीच एक नुकीला मोड़): मोड़ पर बना कोण = ऊपर वाला कोण + नीचे वाला कोण (दोनों एकांतर कोणों का योग)।</li>\n      <li>यदि दो कोणों की भुजाएँ क्रमशः समांतर हों तो कोण या तो बराबर होते हैं या संपूरक।</li>\n    </ul>\n    <h4>5. डिग्री-रेडियन ट्रिक</h4>\n    <ul>\n      <li>π को सीधे 180 रखकर हल करें: 3π/4 = 3 × 180/4 = 135°। 5π/12 = 75°।</li>\n      <li>डिग्री → रेडियन: 180 का कौन-सा भाग है? 135/180 = 3/4 → 3π/4।</li>\n      <li>मिनट/सेकंड में उधार: 90° = 89°60′ = 89°59′60″ — घटाने में उपयोगी।</li>\n    </ul>\n    <div class=\"tip\">परीक्षा चेतावनी: \"प्रतिवर्ती\" और \"वृहत्\" एक ही हैं (180° से 360° के बीच)। 180° स्वयं सरल कोण है, प्रतिवर्ती नहीं; 90° समकोण है, न्यून या अधिक नहीं।</div>\n  ",
  questions: [
    {"q":"एक रेखाखंड के कितने अंत बिंदु होते हैं?","o":["0","1","2","अनंत"],"a":2,"e":"<b>हल:</b><br>चरण 1: रेखाखंड = किसी रेखा का वह भाग जो दो बिंदुओं के बीच सीमित हो।<br>चरण 2: ये दोनों सीमांत बिंदु ही उसके अंत बिंदु हैं, इसलिए उसकी लंबाई निश्चित होती है।<br>अतः उत्तर = <b>2</b><br><b>ध्यान दें:</b> रेखा के 0 और किरण का 1 अंत बिंदु होता है — इन्हें आपस में न मिलाएँ।"},
    {"q":"एक किरण के कितने अंत बिंदु होते हैं?","o":["0","1","2","अनंत"],"a":1,"e":"<b>हल:</b><br>चरण 1: किरण एक प्रारंभिक बिंदु से शुरू होती है।<br>चरण 2: वह केवल एक दिशा में अनंत तक जाती है, दूसरी ओर कोई अंत नहीं।<br>अतः उत्तर = <b>1</b><br><b>ध्यान दें:</b> रेखा → 0 अंत बिंदु, किरण → 1, रेखाखंड → 2।"},
    {"q":"दो भिन्न बिंदुओं से होकर कितनी रेखाएँ खींची जा सकती हैं?","o":["केवल एक","दो","अनंत","एक भी नहीं"],"a":0,"e":"<b>हल:</b><br>चरण 1: NCERT अभिगृहीत: दो भिन्न बिंदुओं से होकर एक और केवल एक रेखा खींची जा सकती है।<br>चरण 2: दूसरी रेखा खींचने पर वह पहली से संपाती हो जाएगी।<br>अतः उत्तर = <b>केवल एक</b><br><b>ध्यान दें:</b> \"अनंत\" रेखाएँ एक बिंदु से होकर खींची जाती हैं, दो बिंदुओं से नहीं।"},
    {"q":"एक बिंदु से होकर कितनी रेखाएँ खींची जा सकती हैं?","o":["केवल एक","केवल दो","केवल तीन","अनगिनत (अनंत)"],"a":3,"e":"<b>हल:</b><br>चरण 1: एक बिंदु से होकर रेखा किसी भी दिशा में खींची जा सकती है।<br>चरण 2: दिशाएँ अनगिनत हैं, इसलिए रेखाएँ भी अनगिनत।<br>अतः उत्तर = <b>अनगिनत (अनंत)</b><br><b>ध्यान दें:</b> दो बिंदु हों तो केवल एक रेखा — प्रश्न में बिंदुओं की संख्या ध्यान से पढ़ें।"},
    {"q":"निम्न में से किसकी लंबाई निश्चित होती है और मापी जा सकती है?","o":["रेखा","किरण","रेखाखंड","रेखा और किरण दोनों"],"a":2,"e":"<b>हल:</b><br>चरण 1: रेखा के दोनों ओर अंत नहीं → लंबाई अनंत।<br>चरण 2: किरण का एक ओर अंत नहीं → लंबाई अनंत।<br>चरण 3: रेखाखंड के दोनों अंत बिंदु हैं → लंबाई निश्चित, मापी जा सकती है।<br>अतः उत्तर = <b>रेखाखंड</b>"},
    {"q":"सूर्य से निकलने वाला प्रकाश ज्यामिति की किस आकृति का उदाहरण है?","o":["रेखाखंड","किरण","रेखा","वक्र"],"a":1,"e":"<b>हल:</b><br>चरण 1: सूर्य = प्रकाश का स्रोत = प्रारंभिक बिंदु।<br>चरण 2: प्रकाश वहाँ से एक दिशा में अनंत तक जाता है।<br>चरण 3: एक प्रारंभिक बिंदु + एक दिशा में अनंत = किरण।<br>अतः उत्तर = <b>किरण</b>"},
    {"q":"तीन या अधिक बिंदु जो एक ही रेखा पर स्थित हों, कहलाते हैं —","o":["संगामी बिंदु","संरेख बिंदु","असंरेख बिंदु","प्रतिच्छेदी बिंदु"],"a":1,"e":"<b>हल:</b><br>चरण 1: जो बिंदु एक ही सरल रेखा पर हों → संरेख (collinear)।<br>चरण 2: जो एक रेखा पर न हों → असंरेख।<br>अतः उत्तर = <b>संरेख बिंदु</b><br><b>ध्यान दें:</b> \"संगामी\" शब्द रेखाओं के लिए है (एक बिंदु से गुजरने वाली रेखाएँ), बिंदुओं के लिए नहीं।"},
    {"q":"तीन या अधिक रेखाएँ जो एक ही बिंदु से होकर गुजरें, कहलाती हैं —","o":["समांतर रेखाएँ","संरेख रेखाएँ","तिर्यक रेखाएँ","संगामी रेखाएँ"],"a":3,"e":"<b>हल:</b><br>चरण 1: तीन या अधिक रेखाएँ एक ही बिंदु से गुजरें → संगामी (concurrent) रेखाएँ।<br>चरण 2: वह साझा बिंदु संगमन बिंदु कहलाता है।<br>अतः उत्तर = <b>संगामी रेखाएँ</b><br><b>ध्यान दें:</b> संरेख = बिंदुओं के लिए; संगामी = रेखाओं के लिए।"},
    {"q":"एक ही तल में स्थित दो समांतर रेखाओं के कितने उभयनिष्ठ बिंदु होते हैं?","o":["एक","दो","अनंत","एक भी नहीं"],"a":3,"e":"<b>हल:</b><br>चरण 1: समांतर रेखाएँ एक ही तल में होती हैं और कितना भी बढ़ाने पर नहीं मिलतीं।<br>चरण 2: न मिलने का अर्थ — कोई उभयनिष्ठ बिंदु नहीं।<br>अतः उत्तर = <b>एक भी नहीं</b><br><b>ध्यान दें:</b> संपाती (एक के ऊपर एक) रेखाओं के अनंत उभयनिष्ठ बिंदु होते हैं, पर वे \"भिन्न\" समांतर रेखाएँ नहीं हैं।"},
    {"q":"दो भिन्न प्रतिच्छेदी रेखाएँ अधिकतम कितने बिंदुओं पर काट सकती हैं?","o":["एक","दो","तीन","अनंत"],"a":0,"e":"<b>हल:</b><br>चरण 1: यदि दो भिन्न रेखाएँ दो बिंदुओं पर मिलें, तो उन दो बिंदुओं से दो रेखाएँ गुजरेंगी।<br>चरण 2: पर दो बिंदुओं से केवल एक ही रेखा गुजर सकती है — विरोधाभास।<br>चरण 3: अतः दो भिन्न रेखाएँ अधिकतम एक बिंदु पर काटती हैं।<br>अतः उत्तर = <b>एक</b>"},
    {"q":"10 बिंदुओं में से कोई भी तीन संरेख नहीं हैं। इन्हें मिलाकर कितनी रेखाएँ खींची जा सकती हैं?","o":["90","45","40","50"],"a":1,"e":"<b>हल:</b><br>चरण 1: हर रेखा के लिए 2 बिंदु चाहिए → रेखाएँ = ⁿC₂ = n(n−1)/2।<br>चरण 2: n = 10 → 10 × 9 / 2।<br>चरण 3: = 90 / 2 = 45।<br>अतः उत्तर = <b>45</b><br><b>ध्यान दें:</b> 90 (= 10 × 9) तब आता है जब 2 से भाग देना भूल जाएँ — AB और BA एक ही रेखा है।"},
    {"q":"12 बिंदुओं में से 5 बिंदु संरेख हैं, शेष में कोई तीन संरेख नहीं। इनसे कितनी भिन्न रेखाएँ बनेंगी?","o":["66","56","57","61"],"a":2,"e":"<b>हल:</b><br>चरण 1: यदि कोई तीन संरेख न होते: ¹²C₂ = 12 × 11 / 2 = 66 रेखाएँ।<br>चरण 2: 5 संरेख बिंदुओं से गिनी गई रेखाएँ: ⁵C₂ = 5 × 4 / 2 = 10 — पर ये वास्तव में एक ही रेखा है।<br>चरण 3: अतः 10 घटाएँ और 1 जोड़ें: 66 − 10 + 1 = 57।<br>अतः उत्तर = <b>57</b><br><b>शॉर्टकट:</b> ⁿC₂ − ᵐC₂ + 1 (m = संरेख बिंदु)।<br><b>ध्यान दें:</b> केवल 10 घटाकर 56 लिखना सामान्य गलती है — वह एक रेखा फिर भी बनती है, इसलिए +1।"},
    {"q":"कितने बिंदुओं (कोई तीन संरेख नहीं) से ठीक 28 रेखाएँ बनती हैं?","o":["7","8","9","14"],"a":1,"e":"<b>हल:</b><br>चरण 1: n(n−1)/2 = 28।<br>चरण 2: n(n−1) = 56।<br>चरण 3: 56 = 8 × 7 (लगातार दो संख्याएँ) → n = 8।<br>अतः उत्तर = <b>8</b><br><b>ध्यान दें:</b> n = 7 लेने पर 7 × 6/2 = 21 ही आता है।"},
    {"q":"6 बिंदुओं में से कोई तीन संरेख नहीं हैं। इनसे कितने त्रिभुज बनाए जा सकते हैं?","o":["15","18","20","24"],"a":2,"e":"<b>हल:</b><br>चरण 1: त्रिभुज के लिए 3 असंरेख बिंदु चाहिए → संख्या = ⁿC₃ = n(n−1)(n−2)/6।<br>चरण 2: n = 6 → 6 × 5 × 4 / 6।<br>चरण 3: = 120 / 6 = 20।<br>अतः उत्तर = <b>20</b><br><b>ध्यान दें:</b> ⁿC₂ = 15 रेखाओं की संख्या है, त्रिभुजों की नहीं।"},
    {"q":"एक तल में 7 रेखाएँ हैं जिनमें कोई दो समांतर नहीं और कोई तीन संगामी नहीं। प्रतिच्छेद बिंदुओं की संख्या है —","o":["21","14","42","35"],"a":0,"e":"<b>हल:</b><br>चरण 1: कोई दो समांतर नहीं → हर दो रेखाएँ ठीक एक बिंदु पर काटती हैं।<br>चरण 2: कोई तीन संगामी नहीं → हर बिंदु अलग।<br>चरण 3: बिंदु = ⁷C₂ = 7 × 6 / 2 = 21।<br>अतः उत्तर = <b>21</b><br><b>ध्यान दें:</b> 42 = 7 × 6 — 2 से भाग देना न भूलें।"},
    {"q":"अंग्रेज़ी अक्षर \"O\" किस प्रकार का वक्र है?","o":["खुला वक्र","सरल बंद वक्र","स्वयं को काटने वाला बंद वक्र","रेखाखंड"],"a":1,"e":"<b>हल:</b><br>चरण 1: \"O\" के दोनों सिरे मिल जाते हैं → बंद वक्र।<br>चरण 2: यह स्वयं को कहीं नहीं काटता → सरल वक्र।<br>अतः उत्तर = <b>सरल बंद वक्र</b><br><b>ध्यान दें:</b> \"8\" जैसी आकृति स्वयं को काटती है — वह सरल बंद वक्र नहीं है।"},
    {"q":"135° का कोण किस प्रकार का है?","o":["न्यून कोण","समकोण","अधिक कोण","प्रतिवर्ती कोण"],"a":2,"e":"<b>हल:</b><br>चरण 1: कोणों का वर्गीकरण: न्यून < 90° < अधिक < 180° < प्रतिवर्ती < 360°।<br>चरण 2: 90° < 135° < 180°।<br>अतः उत्तर = <b>अधिक कोण</b>"},
    {"q":"210° का कोण कहलाता है —","o":["प्रतिवर्ती (वृहत्) कोण","अधिक कोण","सरल कोण","संपूर्ण कोण"],"a":0,"e":"<b>हल:</b><br>चरण 1: 180° < θ < 360° → प्रतिवर्ती (वृहत्) कोण।<br>चरण 2: 180° < 210° < 360°।<br>अतः उत्तर = <b>प्रतिवर्ती (वृहत्) कोण</b><br><b>ध्यान दें:</b> अधिक कोण 180° से कम होता है; 210° उससे बड़ा है।"},
    {"q":"सरल (ऋजु) कोण का माप कितना होता है?","o":["90°","360°","180°","270°"],"a":2,"e":"<b>हल:</b><br>चरण 1: सरल कोण की दोनों भुजाएँ विपरीत दिशाओं में होकर एक सीधी रेखा बनाती हैं।<br>चरण 2: सीधी रेखा पर कोण = आधा चक्कर = 360°/2 = 180°।<br>अतः उत्तर = <b>180°</b>"},
    {"q":"वह कोण जो 0° से अधिक तथा 90° से कम हो, कहलाता है —","o":["अधिक कोण","समकोण","प्रतिवर्ती कोण","न्यून कोण"],"a":3,"e":"<b>हल:</b><br>चरण 1: 0° < θ < 90° → न्यून कोण (acute)।<br>चरण 2: 90° = समकोण, 90°–180° = अधिक कोण।<br>अतः उत्तर = <b>न्यून कोण</b>"},
    {"q":"यदि दो कोणों का योग 90° हो तो वे कहलाते हैं —","o":["संपूरक कोण","प्रतिवर्ती कोण","शीर्षाभिमुख कोण","पूरक कोण"],"a":3,"e":"<b>हल:</b><br>चरण 1: दो कोणों का योग 90° → पूरक (complementary)।<br>चरण 2: दो कोणों का योग 180° → संपूरक (supplementary)।<br>अतः उत्तर = <b>पूरक कोण</b><br><b>शॉर्टकट:</b> \"पूरक\" छोटा शब्द → छोटा योग 90°; \"संपूरक\" बड़ा शब्द → बड़ा योग 180°।"},
    {"q":"40° का पूरक कोण कितना है?","o":["50°","140°","40°","320°"],"a":0,"e":"<b>हल:</b><br>चरण 1: पूरक = 90° − कोण।<br>चरण 2: 90° − 40° = 50°।<br>अतः उत्तर = <b>50°</b><br><b>ध्यान दें:</b> 140° = 180° − 40° संपूरक है, पूरक नहीं।"},
    {"q":"75° का संपूरक कोण कितना है?","o":["15°","95°","285°","105°"],"a":3,"e":"<b>हल:</b><br>चरण 1: संपूरक = 180° − कोण।<br>चरण 2: 180° − 75° = 105°।<br>अतः उत्तर = <b>105°</b><br><b>ध्यान दें:</b> 15° पूरक है (90 − 75), 285° प्रतिवर्ती (360 − 75)।"},
    {"q":"110° का प्रतिवर्ती कोण कितना है?","o":["250°","70°","290°","160°"],"a":0,"e":"<b>हल:</b><br>चरण 1: प्रतिवर्ती कोण = 360° − कोण।<br>चरण 2: 360° − 110° = 250°।<br>अतः उत्तर = <b>250°</b><br><b>ध्यान दें:</b> 70° संपूरक है (180 − 110)।"},
    {"q":"निम्न में से कौन-सा युग्म पूरक कोणों का है?","o":["47°, 53°","80°, 100°","45°, 55°","37°, 53°"],"a":3,"e":"<b>हल:</b><br>चरण 1: पूरक युग्म का योग 90° होना चाहिए।<br>चरण 2: 47 + 53 = 100 ✗; 80 + 100 = 180 ✗ (संपूरक); 45 + 55 = 100 ✗।<br>चरण 3: 37 + 53 = 90 ✓।<br>अतः उत्तर = <b>37°, 53°</b>"},
    {"q":"एक कोण अपने पूरक का दोगुना है। वह कोण है —","o":["60°","30°","45°","120°"],"a":0,"e":"<b>हल:</b><br>चरण 1: माना कोण = x, पूरक = 90 − x।<br>चरण 2: x = 2(90 − x) = 180 − 2x।<br>चरण 3: 3x = 180 → x = 60°।<br>अतः उत्तर = <b>60°</b><br><b>शॉर्टकट:</b> कोण : पूरक = 2 : 1 → 90 × 2/3 = 60°।<br><b>ध्यान दें:</b> 30° पूरक है, कोण नहीं।"},
    {"q":"एक कोण अपने संपूरक का एक-चौथाई है। वह कोण है —","o":["45°","30°","144°","36°"],"a":3,"e":"<b>हल:</b><br>चरण 1: माना कोण = x, संपूरक = 180 − x।<br>चरण 2: x = (180 − x)/4 → 4x = 180 − x।<br>चरण 3: 5x = 180 → x = 36°।<br>अतः उत्तर = <b>36°</b><br><b>शॉर्टकट:</b> कोण : संपूरक = 1 : 4 → 180 × 1/5 = 36°।<br><b>ध्यान दें:</b> 144° संपूरक है।"},
    {"q":"एक कोण अपने पूरक से 20° अधिक है। वह कोण है —","o":["35°","55°","65°","45°"],"a":1,"e":"<b>हल:</b><br>चरण 1: माना कोण = x, पूरक = 90 − x।<br>चरण 2: x − (90 − x) = 20 → 2x − 90 = 20।<br>चरण 3: 2x = 110 → x = 55°।<br>अतः उत्तर = <b>55°</b><br><b>शॉर्टकट:</b> कोण = (90 + अंतर)/2 = (90 + 20)/2 = 55°।<br><b>ध्यान दें:</b> 35° पूरक है।"},
    {"q":"किसी कोण के पूरक और संपूरक का योग 210° है। वह कोण है —","o":["60°","45°","30°","40°"],"a":2,"e":"<b>हल:</b><br>चरण 1: पूरक = 90 − x, संपूरक = 180 − x।<br>चरण 2: (90 − x) + (180 − x) = 210 → 270 − 2x = 210।<br>चरण 3: 2x = 60 → x = 30°।<br>अतः उत्तर = <b>30°</b><br><b>शॉर्टकट:</b> x = (270 − योग)/2 = 60/2 = 30°।"},
    {"q":"किसी कोण का संपूरक उसके पूरक का चार गुना है। वह कोण है —","o":["60°","30°","45°","75°"],"a":0,"e":"<b>हल:</b><br>चरण 1: संपूरक = 180 − x, पूरक = 90 − x।<br>चरण 2: 180 − x = 4(90 − x) = 360 − 4x।<br>चरण 3: 3x = 180 → x = 60°।<br>अतः उत्तर = <b>60°</b><br><b>शॉर्टकट:</b> संपूरक − पूरक = 90° सदा; यहाँ 4P − P = 90 → पूरक P = 30° → कोण = 60°।"},
    {"q":"दो पूरक कोणों का अनुपात 2 : 3 है। बड़ा कोण है —","o":["36°","54°","72°","108°"],"a":1,"e":"<b>हल:</b><br>चरण 1: पूरक कोणों का योग 90°; अनुपात 2 : 3 → कुल भाग 5।<br>चरण 2: 1 भाग = 90/5 = 18°।<br>चरण 3: बड़ा कोण = 3 × 18 = 54° (छोटा 36°)।<br>अतः उत्तर = <b>54°</b><br><b>ध्यान दें:</b> 36° छोटा कोण है।"},
    {"q":"दो संपूरक कोणों का अनुपात 4 : 5 है। छोटा कोण है —","o":["100°","72°","40°","80°"],"a":3,"e":"<b>हल:</b><br>चरण 1: संपूरक कोणों का योग 180°; अनुपात 4 : 5 → कुल भाग 9।<br>चरण 2: 1 भाग = 180/9 = 20°।<br>चरण 3: छोटा कोण = 4 × 20 = 80° (बड़ा 100°)।<br>अतः उत्तर = <b>80°</b><br><b>ध्यान दें:</b> 100° बड़ा कोण है।"},
    {"q":"दो संपूरक कोणों का अंतर 40° है। बड़ा कोण है —","o":["70°","100°","110°","130°"],"a":2,"e":"<b>हल:</b><br>चरण 1: योग = 180°, अंतर = 40°।<br>चरण 2: बड़ा = (योग + अंतर)/2 = (180 + 40)/2।<br>चरण 3: = 220/2 = 110° (छोटा = 70°)।<br>अतः उत्तर = <b>110°</b>"},
    {"q":"एक कोण अपने प्रतिवर्ती कोण का 1/5 है। वह कोण है —","o":["72°","60°","45°","30°"],"a":1,"e":"<b>हल:</b><br>चरण 1: प्रतिवर्ती कोण = 360 − x।<br>चरण 2: x = (360 − x)/5 → 5x = 360 − x।<br>चरण 3: 6x = 360 → x = 60°।<br>अतः उत्तर = <b>60°</b><br><b>शॉर्टकट:</b> 1 : 5 → 360 × 1/6 = 60°।<br><b>ध्यान दें:</b> 72° = 360/5 तब आता है जब x को भी 360 में से नहीं घटाते।"},
    {"q":"किसी भी कोण के संपूरक और पूरक का अंतर सदा होता है —","o":["90°","180°","45°","कोण पर निर्भर"],"a":0,"e":"<b>हल:</b><br>चरण 1: संपूरक = 180 − x, पूरक = 90 − x।<br>चरण 2: अंतर = (180 − x) − (90 − x) = 90°।<br>चरण 3: x कट जाता है → उत्तर कोण पर निर्भर नहीं।<br>अतः उत्तर = <b>90°</b>"},
    {"q":"रैखिक युग्म बनाने वाले दो कोणों का योग होता है —","o":["90°","360°","180°","120°"],"a":2,"e":"<b>हल:</b><br>चरण 1: रैखिक युग्म = दो आसन्न कोण जिनकी अउभयनिष्ठ भुजाएँ एक सीधी रेखा बनाती हैं।<br>चरण 2: सीधी रेखा पर कोण 180° → योग 180°।<br>अतः उत्तर = <b>180°</b>"},
    {"q":"रैखिक युग्म के कोण सदा होते हैं —","o":["आसन्न एवं पूरक","शीर्षाभिमुख","एकांतर","आसन्न एवं संपूरक"],"a":3,"e":"<b>हल:</b><br>चरण 1: रैखिक युग्म के कोण एक भुजा व शीर्ष साझा करते हैं → आसन्न।<br>चरण 2: उनका योग 180° → संपूरक।<br>अतः उत्तर = <b>आसन्न एवं संपूरक</b><br><b>ध्यान दें:</b> \"आसन्न एवं पूरक\" तब होता जब योग 90° होता।"},
    {"q":"रैखिक युग्म में यदि एक कोण न्यून है तो दूसरा कोण होगा —","o":["अधिक कोण","न्यून कोण","समकोण","प्रतिवर्ती कोण"],"a":0,"e":"<b>हल:</b><br>चरण 1: रैखिक युग्म: x + y = 180° → y = 180° − x।<br>चरण 2: x न्यून है, अर्थात x, 90° से कम है।<br>चरण 3: तब y = 180° − x, 90° से अधिक और 180° से कम होगा।<br>चरण 4: 90° और 180° के बीच का कोण = अधिक कोण।<br>अतः उत्तर = <b>अधिक कोण</b><br><b>शॉर्टकट:</b> उदाहरण लें: x = 30° → y = 150° (अधिक कोण)।"},
    {"q":"दो रेखाओं के प्रतिच्छेद से बने शीर्षाभिमुख कोण सदा होते हैं —","o":["पूरक","संपूरक","बराबर","समकोण"],"a":2,"e":"<b>हल:</b><br>चरण 1: प्रतिच्छेद पर ∠1 + ∠2 = 180° और ∠2 + ∠3 = 180° (रैखिक युग्म)।<br>चरण 2: दोनों से ∠1 = ∠3।<br>अतः उत्तर = <b>बराबर</b><br><b>ध्यान दें:</b> आसन्न कोण संपूरक होते हैं; शीर्षाभिमुख कोण बराबर।"},
    {"q":"दो रेखाएँ प्रतिच्छेद करती हैं और एक कोण 50° है। इसका शीर्षाभिमुख कोण तथा आसन्न कोण क्रमशः हैं —","o":["130°, 50°","40°, 140°","50°, 40°","50°, 130°"],"a":3,"e":"<b>हल:</b><br>चरण 1: शीर्षाभिमुख कोण बराबर → 50°।<br>चरण 2: आसन्न कोण, 50° के साथ रैखिक युग्म बनाता है → 180° − 50° = 130°।<br>अतः उत्तर = <b>50°, 130°</b><br><b>ध्यान दें:</b> क्रम उलटने (130°, 50°) वाला विकल्प गलत है — \"क्रमशः\" पर ध्यान दें।"},
    {"q":"दो रेखाओं के प्रतिच्छेद से बने चार कोणों में से तीन का योग 290° है। चौथा कोण है —","o":["110°","70°","90°","20°"],"a":1,"e":"<b>हल:</b><br>चरण 1: दो रेखाओं के प्रतिच्छेद से बने चारों कोणों का योग = 360°।<br>चरण 2: चौथा कोण = 360° − 290° = 70°।<br>चरण 3: जाँच: कोण 70°, 110°, 70°, 110° → योग 360° ✓।<br>अतः उत्तर = <b>70°</b>"},
    {"q":"रैखिक युग्म के दो कोण (3x + 20)° और (2x + 10)° हैं। x का मान है —","o":["25","30","32","34"],"a":1,"e":"<b>हल:</b><br>चरण 1: रैखिक युग्म → योग 180°।<br>चरण 2: (3x + 20) + (2x + 10) = 180 → 5x + 30 = 180।<br>चरण 3: 5x = 150 → x = 30 (कोण 110° और 70°)।<br>अतः उत्तर = <b>30</b>"},
    {"q":"दो शीर्षाभिमुख कोण (3x − 10)° और (2x + 25)° हैं। प्रत्येक कोण का माप है —","o":["85°","35°","105°","95°"],"a":3,"e":"<b>हल:</b><br>चरण 1: शीर्षाभिमुख कोण बराबर: 3x − 10 = 2x + 25।<br>चरण 2: x = 35।<br>चरण 3: कोण = 3 × 35 − 10 = 95° (जाँच: 2 × 35 + 25 = 95° ✓)।<br>अतः उत्तर = <b>95°</b><br><b>ध्यान दें:</b> 35 तो x का मान है, कोण नहीं।"},
    {"q":"एक बिंदु के चारों ओर बने सभी कोणों का योग होता है —","o":["180°","270°","360°","540°"],"a":2,"e":"<b>हल:</b><br>चरण 1: एक बिंदु के चारों ओर एक पूरा चक्कर बनता है।<br>चरण 2: पूरा चक्कर = संपूर्ण कोण = 360°।<br>अतः उत्तर = <b>360°</b>"},
    {"q":"दो समांतर रेखाओं को एक तिर्यक रेखा काटती है। एकांतर अंतः कोणों में से एक 72° है, तो दूसरा है —","o":["108°","72°","18°","144°"],"a":1,"e":"<b>हल:</b><br>चरण 1: समांतर रेखाएँ + तिर्यक रेखा → एकांतर अंतः कोण बराबर।<br>चरण 2: दूसरा कोण = 72°।<br>अतः उत्तर = <b>72°</b><br><b>ध्यान दें:</b> 108° = 180 − 72 सह-अंतः (एक ही ओर के) कोण के लिए है।"},
    {"q":"समांतर रेखाओं पर तिर्यक रेखा के एक ही ओर के अंतः कोणों का योग होता है —","o":["90°","360°","शून्य","180°"],"a":3,"e":"<b>हल:</b><br>चरण 1: एक ही ओर के अंतः कोण (सह-अंतः कोण) संपूरक होते हैं।<br>चरण 2: अतः योग = 180°।<br>अतः उत्तर = <b>180°</b>"},
    {"q":"समांतर रेखाओं पर तिर्यक रेखा के एक ही ओर के अंतः कोणों का अनुपात 2 : 7 है। छोटा कोण है —","o":["40°","20°","140°","50°"],"a":0,"e":"<b>हल:</b><br>चरण 1: एक ही ओर के अंतः कोणों का योग 180°; अनुपात 2 : 7 → कुल 9 भाग।<br>चरण 2: 1 भाग = 180/9 = 20°।<br>चरण 3: छोटा कोण = 2 × 20 = 40° (बड़ा 140°)।<br>अतः उत्तर = <b>40°</b>"},
    {"q":"समांतर रेखाओं पर तिर्यक रेखा के एक ही ओर के अंतः कोण (2x + 10)° और (3x − 5)° हैं। बड़ा कोण है —","o":["80°","100°","95°","105°"],"a":1,"e":"<b>हल:</b><br>चरण 1: एक ही ओर के अंतः कोण → योग 180°।<br>चरण 2: (2x + 10) + (3x − 5) = 180 → 5x + 5 = 180 → x = 35।<br>चरण 3: कोण: 2 × 35 + 10 = 80°, 3 × 35 − 5 = 100°।<br>अतः उत्तर = <b>100°</b><br><b>ध्यान दें:</b> 80° छोटा कोण है।"},
    {"q":"दो समांतर रेखाओं पर संगत कोण (5x − 20)° और (3x + 30)° हैं। संगत कोण का माप है —","o":["25°","75°","105°","115°"],"a":2,"e":"<b>हल:</b><br>चरण 1: समांतर रेखाओं पर संगत कोण बराबर: 5x − 20 = 3x + 30।<br>चरण 2: 2x = 50 → x = 25।<br>चरण 3: कोण = 5 × 25 − 20 = 105°।<br>अतः उत्तर = <b>105°</b><br><b>ध्यान दें:</b> 25 x का मान है, कोण नहीं।"},
    {"q":"एक तिर्यक रेखा दो रेखाओं को काटती है। कुल कितने कोण बनते हैं?","o":["4","6","8","12"],"a":2,"e":"<b>हल:</b><br>चरण 1: तिर्यक रेखा दोनों रेखाओं को एक-एक बिंदु पर काटती है → 2 प्रतिच्छेद बिंदु।<br>चरण 2: प्रत्येक बिंदु पर 4 कोण।<br>चरण 3: कुल = 2 × 4 = 8 (4 अंतः + 4 बाह्य)।<br>अतः उत्तर = <b>8</b>"},
    {"q":"दो समांतर रेखाओं को एक तिर्यक रेखा (जो लंब नहीं है) काटे तो बने 8 कोणों में कितने भिन्न माप होते हैं?","o":["4","2","1","8"],"a":1,"e":"<b>हल:</b><br>चरण 1: संगत, एकांतर व शीर्षाभिमुख कोण बराबर → सभी कोण x या 180° − x।<br>चरण 2: तिर्यक लंब नहीं → x ≠ 90°, अतः x ≠ 180° − x।<br>अतः उत्तर = <b>2</b><br><b>ध्यान दें:</b> यदि तिर्यक रेखा लंब होती तो सभी 8 कोण 90° — केवल 1 माप।"},
    {"q":"यदि तिर्यक रेखा दो समांतर रेखाओं में से एक पर लंब है, तो दूसरी पर वह —","o":["लंब होगी","45° पर झुकी होगी","समांतर होगी","कुछ कहा नहीं जा सकता"],"a":0,"e":"<b>हल:</b><br>चरण 1: एक रेखा पर लंब → वहाँ कोण 90°।<br>चरण 2: समांतर रेखाओं पर संगत कोण बराबर → दूसरी पर भी 90°।<br>अतः उत्तर = <b>लंब होगी</b>"},
    {"q":"यदि दो रेखाओं को काटने वाली तिर्यक रेखा से बने एकांतर अंतः कोण बराबर हों, तो दोनों रेखाएँ —","o":["परस्पर लंब हैं","संगामी हैं","प्रतिच्छेदी हैं","समांतर हैं"],"a":3,"e":"<b>हल:</b><br>चरण 1: एकांतर कोण प्रमेय: समांतर रेखाएँ → एकांतर कोण बराबर।<br>चरण 2: इसका विलोम भी सत्य: एकांतर कोण बराबर → रेखाएँ समांतर।<br>अतः उत्तर = <b>समांतर हैं</b>"},
    {"q":"दो समांतर रेखाओं पर एक तिर्यक रेखा से बना एक बाह्य कोण 115° है। उसी ओर का संगत अंतः कोण तथा एक ही ओर का दूसरा बाह्य कोण क्रमशः हैं —","o":["115°, 65°","65°, 115°","115°, 115°","65°, 65°"],"a":0,"e":"<b>हल:</b><br>चरण 1: संगत कोण बराबर → संगत अंतः कोण = 115°।<br>चरण 2: तिर्यक रेखा के एक ही ओर के दो बाह्य कोण संपूरक → 180° − 115° = 65°।<br>अतः उत्तर = <b>115°, 65°</b><br><b>ध्यान दें:</b> क्रम उलटा (65°, 115°) गलत है।"},
    {"q":"रैखिक युग्म बनाने वाले दोनों कोणों के समद्विभाजकों के बीच का कोण होता है —","o":["45°","60°","180°","90°"],"a":3,"e":"<b>हल:</b><br>चरण 1: रैखिक युग्म: x और 180° − x।<br>चरण 2: समद्विभाजकों के बीच कोण = x/2 + (180 − x)/2।<br>चरण 3: = 180/2 = 90°।<br>अतः उत्तर = <b>90°</b><br><b>शॉर्टकट:</b> आसन्न कोणों के समद्विभाजकों के बीच कोण = (कोणों का योग)/2।"},
    {"q":"दो आसन्न पूरक कोणों के समद्विभाजकों के बीच का कोण होता है —","o":["90°","30°","45°","60°"],"a":2,"e":"<b>हल:</b><br>चरण 1: आसन्न पूरक कोण: x और 90° − x।<br>चरण 2: समद्विभाजकों के बीच कोण = x/2 + (90 − x)/2 = 90/2।<br>चरण 3: = 45°।<br>अतः उत्तर = <b>45°</b>"},
    {"q":"100° के कोण को समद्विभाजित किया गया। प्रत्येक भाग का पूरक कोण है —","o":["40°","50°","130°","80°"],"a":0,"e":"<b>हल:</b><br>चरण 1: प्रत्येक भाग = 100°/2 = 50°।<br>चरण 2: 50° का पूरक = 90° − 50° = 40°।<br>अतः उत्तर = <b>40°</b><br><b>ध्यान दें:</b> 50° प्रत्येक भाग है, पूरक नहीं; 130° उसका संपूरक है।"},
    {"q":"घड़ी में ठीक 4 बजे घंटे और मिनट की सुइयों के बीच कोण है —","o":["100°","150°","60°","120°"],"a":3,"e":"<b>हल:</b><br>चरण 1: सूत्र: θ = |30H − 5.5M| (H = घंटा, M = मिनट)।<br>चरण 2: H = 4, M = 0 → θ = |120 − 0| = 120°।<br>अतः उत्तर = <b>120°</b><br><b>शॉर्टकट:</b> हर घंटे का अंतर 30° → 4 घंटे = 120°।"},
    {"q":"घड़ी में 3 बजकर 40 मिनट पर दोनों सुइयों के बीच कोण है —","o":["120°","130°","140°","150°"],"a":1,"e":"<b>हल:</b><br>चरण 1: सूत्र: θ = |30H − 5.5M|।<br>चरण 2: H = 3, M = 40 → 30 × 3 = 90, 5.5 × 40 = 220।<br>चरण 3: θ = |90 − 220| = 130°।<br>अतः उत्तर = <b>130°</b>"},
    {"q":"घड़ी में 7 बजकर 20 मिनट पर दोनों सुइयों के बीच कोण है —","o":["100°","90°","110°","120°"],"a":0,"e":"<b>हल:</b><br>चरण 1: सूत्र: θ = |30H − 5.5M|।<br>चरण 2: H = 7, M = 20 → 30 × 7 = 210, 5.5 × 20 = 110।<br>चरण 3: θ = |210 − 110| = 100°।<br>अतः उत्तर = <b>100°</b>"},
    {"q":"घड़ी में 9 बजकर 15 मिनट पर दोनों सुइयों के बीच छोटा कोण है —","o":["187.5°","180°","172.5°","165°"],"a":2,"e":"<b>हल:</b><br>चरण 1: सूत्र: θ = |30H − 5.5M| (H = घंटा, M = मिनट); यदि θ 180° से अधिक आए तो छोटा कोण = 360° − θ।<br>चरण 2: H = 9, M = 15 → 30 × 9 = 270, 5.5 × 15 = 82.5।<br>चरण 3: θ = |270 − 82.5| = 187.5° (180° से अधिक)।<br>चरण 4: छोटा कोण = 360° − 187.5° = 172.5°।<br>अतः उत्तर = <b>172.5°</b><br><b>ध्यान दें:</b> 187.5° बड़ा (प्रतिवर्ती) कोण है — प्रश्न छोटा कोण पूछ रहा है।"},
    {"q":"घड़ी में 2 बजकर 30 मिनट पर दोनों सुइयों के बीच कोण है —","o":["90°","115°","120°","105°"],"a":3,"e":"<b>हल:</b><br>चरण 1: सूत्र: θ = |30H − 5.5M| (H = घंटा, M = मिनट); यदि θ 180° से अधिक आए तो छोटा कोण = 360° − θ।<br>चरण 2: H = 2, M = 30 → 30 × 2 = 60, 5.5 × 30 = 165।<br>चरण 3: θ = |60 − 165| = 105°।<br>अतः उत्तर = <b>105°</b><br><b>ध्यान दें:</b> केवल अंकों (2 और 6) के बीच 4 खाने × 30 = 120° लेना गलत है — घंटे की सुई भी 15° आगे बढ़ चुकी है।"},
    {"q":"घड़ी में 8 बजकर 20 मिनट पर दोनों सुइयों के बीच कोण है —","o":["120°","140°","110°","130°"],"a":3,"e":"<b>हल:</b><br>चरण 1: सूत्र: θ = |30H − 5.5M| (H = घंटा, M = मिनट); यदि θ 180° से अधिक आए तो छोटा कोण = 360° − θ।<br>चरण 2: H = 8, M = 20 → 30 × 8 = 240, 5.5 × 20 = 110।<br>चरण 3: θ = |240 − 110| = 130°।<br>अतः उत्तर = <b>130°</b>"},
    {"q":"घड़ी में 10 बजकर 10 मिनट पर दोनों सुइयों के बीच छोटा कोण है —","o":["115°","245°","125°","105°"],"a":0,"e":"<b>हल:</b><br>चरण 1: सूत्र: θ = |30H − 5.5M| (H = घंटा, M = मिनट); यदि θ 180° से अधिक आए तो छोटा कोण = 360° − θ।<br>चरण 2: H = 10, M = 10 → 30 × 10 = 300, 5.5 × 10 = 55।<br>चरण 3: θ = |300 − 55| = 245° (180° से अधिक)।<br>चरण 4: छोटा कोण = 360° − 245° = 115°।<br>अतः उत्तर = <b>115°</b><br><b>ध्यान दें:</b> 245° बड़ा कोण है।"},
    {"q":"घड़ी की घंटे की सुई एक मिनट में कितने अंश घूमती है?","o":["1°","6°","1/2°","30°"],"a":2,"e":"<b>हल:</b><br>चरण 1: घंटे की सुई 12 घंटे = 720 मिनट में 360° घूमती है।<br>चरण 2: 1 मिनट में = 360/720 = 1/2°।<br>अतः उत्तर = <b>1/2°</b><br><b>ध्यान दें:</b> 30° घंटे की सुई की प्रति घंटा गति है।"},
    {"q":"घड़ी की मिनट की सुई एक मिनट में कितने अंश घूमती है?","o":["1/2°","6°","5.5°","30°"],"a":1,"e":"<b>हल:</b><br>चरण 1: मिनट की सुई 60 मिनट में 360° घूमती है।<br>चरण 2: 1 मिनट में = 360/60 = 6°।<br>अतः उत्तर = <b>6°</b>"},
    {"q":"मिनट की सुई, घंटे की सुई की अपेक्षा प्रति मिनट कितना अधिक घूमती है?","o":["6°","5°","13/2°","11/2°"],"a":3,"e":"<b>हल:</b><br>चरण 1: मिनट की सुई: 6° प्रति मिनट; घंटे की सुई: 1/2° प्रति मिनट।<br>चरण 2: सापेक्ष गति = 6 − 1/2 = 11/2° = 5.5° प्रति मिनट।<br>अतः उत्तर = <b>11/2°</b><br><b>शॉर्टकट:</b> यही 5.5 घड़ी के सूत्र θ = |30H − 5.5M| में आता है।"},
    {"q":"घड़ी की सेकंड की सुई एक सेकंड में कितने अंश घूमती है?","o":["6°","1°","0.1°","60°"],"a":0,"e":"<b>हल:</b><br>चरण 1: सेकंड की सुई 60 सेकंड में 360° घूमती है।<br>चरण 2: 1 सेकंड में = 360/60 = 6°।<br>अतः उत्तर = <b>6°</b>"},
    {"q":"8:00 बजे से 11:30 बजे तक घंटे की सुई कितने अंश घूमती है?","o":["100°","105°","120°","90°"],"a":1,"e":"<b>हल:</b><br>चरण 1: 8:00 से 11:30 तक समय = 3 घंटे 30 मिनट = 3.5 घंटे।<br>चरण 2: घंटे की सुई = 30° प्रति घंटा।<br>चरण 3: 3.5 × 30 = 105°।<br>अतः उत्तर = <b>105°</b><br><b>ध्यान दें:</b> केवल 3 घंटे लेकर 90° लिखना गलत — 30 मिनट के 15° भी जोड़ें।"},
    {"q":"12 घंटे में घड़ी की दोनों सुइयाँ कितनी बार संपाती होती (मिलती) हैं?","o":["12","24","11","22"],"a":2,"e":"<b>हल:</b><br>चरण 1: सापेक्ष गति 5.5°/मिनट → एक बार मिलने के बाद दोबारा मिलने में 360/5.5 = 720/11 = 65 5/11 मिनट।<br>चरण 2: 12 घंटे = 720 मिनट → 720 ÷ (720/11) = 11 बार।<br>चरण 3: कारण: 11 से 1 के बीच केवल 12:00 पर एक ही बार मिलती हैं।<br>अतः उत्तर = <b>11</b><br><b>ध्यान दें:</b> 24 घंटे में 22 बार; 12 या 24 सामान्य गलत उत्तर हैं।"},
    {"q":"एक दिन (24 घंटे) में घड़ी की सुइयाँ कितनी बार परस्पर समकोण बनाती हैं?","o":["48","24","22","44"],"a":3,"e":"<b>हल:</b><br>चरण 1: 12 घंटे में सुइयाँ 22 बार समकोण बनाती हैं (सामान्यतः हर घंटे 2 बार, पर 2–4 और 8–10 के बीच 3 के और 9 के समकोण साझा होने से 24 − 2 = 22)।<br>चरण 2: 24 घंटे में = 2 × 22 = 44।<br>अतः उत्तर = <b>44</b><br><b>ध्यान दें:</b> 48 (= 24 × 2) गलत है।"},
    {"q":"3 और 4 बजे के बीच किस समय घड़ी की दोनों सुइयाँ संपाती होंगी?","o":["3 बजकर 15 मिनट","3 बजकर 16 मिनट","3 बजकर 17 3/11 मिनट","3 बजकर 16 4/11 मिनट"],"a":3,"e":"<b>हल:</b><br>चरण 1: संपाती → θ = 0: 30 × 3 − 5.5M = 0।<br>चरण 2: 5.5M = 90 → M = 90/5.5 = 180/11।<br>चरण 3: 180/11 = 16 4/11 मिनट।<br>अतः उत्तर = <b>3 बजकर 16 4/11 मिनट</b><br><b>शॉर्टकट:</b> H बजे के बाद संपाती समय = (60/11) × H = 60 × 3/11 = 180/11 मिनट।"},
    {"q":"2 और 3 बजे के बीच घड़ी की सुइयाँ पहली बार किस समय समकोण बनाएँगी?","o":["2 बजकर 27 3/11 मिनट","2 बजकर 30 मिनट","2 बजकर 25 मिनट","2 बजकर 26 2/11 मिनट"],"a":0,"e":"<b>हल:</b><br>चरण 1: समकोण → |30 × 2 − 5.5M| = 90 → |60 − 5.5M| = 90।<br>चरण 2: 60 − 5.5M = 90 → M ऋणात्मक (असंभव)।<br>चरण 3: 5.5M − 60 = 90 → 5.5M = 150 → M = 300/11 = 27 3/11 मिनट।<br>अतः उत्तर = <b>2 बजकर 27 3/11 मिनट</b>"},
    {"q":"4 और 5 बजे के बीच किस समय घड़ी की सुइयाँ एक-दूसरे के विपरीत (180°) होंगी?","o":["4 बजकर 50 मिनट","4 बजकर 54 6/11 मिनट","4 बजकर 52 8/11 मिनट","4 बजकर 55 मिनट"],"a":1,"e":"<b>हल:</b><br>चरण 1: विपरीत → θ = 180°: |30 × 4 − 5.5M| = 180।<br>चरण 2: 5.5M − 120 = 180 → 5.5M = 300।<br>चरण 3: M = 300/5.5 = 600/11 = 54 6/11 मिनट।<br>अतः उत्तर = <b>4 बजकर 54 6/11 मिनट</b>"},
    {"q":"1° कितने सेकंड (″) के बराबर है?","o":["60″","360″","3600″","100″"],"a":2,"e":"<b>हल:</b><br>चरण 1: 1° = 60′ (मिनट), 1′ = 60″ (सेकंड)।<br>चरण 2: 1° = 60 × 60 = 3600″।<br>अतः उत्तर = <b>3600″</b>"},
    {"q":"25.5° को डिग्री-मिनट में लिखें —","o":["25°50′","25°30′","25°5′","25°3′"],"a":1,"e":"<b>हल:</b><br>चरण 1: 25.5° = 25° + 0.5°।<br>चरण 2: 0.5° = 0.5 × 60′ = 30′।<br>चरण 3: = 25°30′।<br>अतः उत्तर = <b>25°30′</b><br><b>ध्यान दें:</b> 25°50′ — दशमलव .5 को सीधे 50′ लिखना गलत; 1° = 60′, 100′ नहीं।"},
    {"q":"45°30′ + 30°45′ का मान है —","o":["75°15′","76°15′","76°25′","77°15′"],"a":1,"e":"<b>हल:</b><br>चरण 1: डिग्री और मिनट अलग-अलग जोड़ें: 45° + 30° = 75°, 30′ + 45′ = 75′।<br>चरण 2: 75′ = 60′ + 15′ = 1°15′।<br>चरण 3: 75° + 1°15′ = 76°15′।<br>अतः उत्तर = <b>76°15′</b>"},
    {"q":"35°24′ का पूरक कोण है —","o":["55°36′","54°76′","54°36′","55°24′"],"a":2,"e":"<b>हल:</b><br>चरण 1: पूरक = 90° − 35°24′।<br>चरण 2: 90° = 89°60′ लिखें।<br>चरण 3: 89°60′ − 35°24′ = 54°36′।<br>अतः उत्तर = <b>54°36′</b><br><b>ध्यान दें:</b> 54°76′ — मिनट 60 से कम ही होने चाहिए।"},
    {"q":"π/3 रेडियन कितने अंश के बराबर है?","o":["30°","45°","90°","60°"],"a":3,"e":"<b>हल:</b><br>चरण 1: π रेडियन = 180°।<br>चरण 2: π/3 = 180°/3 = 60°।<br>अतः उत्तर = <b>60°</b>"},
    {"q":"135° को रेडियन में लिखें —","o":["2π/3","3π/4","5π/6","π/4"],"a":1,"e":"<b>हल:</b><br>चरण 1: अंश → रेडियन: × π/180।<br>चरण 2: 135 × π/180 = 3π/4 (135/180 = 3/4)।<br>अतः उत्तर = <b>3π/4</b>"},
    {"q":"1 रेडियन लगभग कितने अंश के बराबर है?","o":["45°","60°","90°","57°16′"],"a":3,"e":"<b>हल:</b><br>चरण 1: π रेडियन = 180° → 1 रेडियन = 180°/π।<br>चरण 2: π = 22/7 लेकर: 180 × 7/22 = 57.27° ≈ 57°16′।<br>अतः उत्तर = <b>57°16′</b><br><b>ध्यान दें:</b> वास्तविक मान ≈ 57.3°; विकल्पों में यही निकटतम है।"},
    {"q":"घड़ी की मिनट की सुई 20 मिनट में कितने रेडियन घूमती है?","o":["π/3","π/2","2π/3","π"],"a":2,"e":"<b>हल:</b><br>चरण 1: मिनट की सुई 6° प्रति मिनट → 20 मिनट में 120°।<br>चरण 2: 120 × π/180 = 2π/3 रेडियन।<br>अतः उत्तर = <b>2π/3</b><br><b>शॉर्टकट:</b> 20 मिनट = 1/3 चक्कर = 2π/3।"},
    {"q":"∠AOB = 80° है। किरण OC, ∠AOB को समद्विभाजित करती है और किरण OD, ∠AOC को समद्विभाजित करती है। ∠DOB का मान क्या है?","o":["40°","60°","20°","50°"],"a":1,"e":"<b>हल:</b><br>चरण 1: OC समद्विभाजक → ∠AOC = ∠COB = 80/2 = 40°।<br>चरण 2: OD, ∠AOC का समद्विभाजक → ∠DOC = 40/2 = 20°।<br>चरण 3: ∠DOB = ∠DOC + ∠COB = 20° + 40° = 60°।<br>अतः उत्तर = <b>60°</b><br><b>ध्यान दें:</b> 20° = ∠AOD या ∠DOC है, ∠DOB नहीं।"},
    {"q":"एक सरल रेखा के एक बिंदु पर, रेखा की एक ही ओर बने तीन आसन्न कोण x, 2x और 3x हैं। सबसे बड़ा कोण कितना है?","o":["60°","120°","90°","30°"],"a":2,"e":"<b>हल:</b><br>चरण 1: सरल रेखा पर एक ही ओर के कोणों का योग = 180°।<br>चरण 2: x + 2x + 3x = 180 → 6x = 180 → x = 30°।<br>चरण 3: सबसे बड़ा = 3x = 90°।<br>अतः उत्तर = <b>90°</b><br><b>ध्यान दें:</b> 30° x का मान है।"},
    {"q":"एक बिंदु के चारों ओर बने चार कोण 2x, 3x, 4x और 6x हैं। सबसे बड़ा कोण कितना है?","o":["144°","120°","96°","72°"],"a":0,"e":"<b>हल:</b><br>चरण 1: एक बिंदु के चारों ओर योग = 360°।<br>चरण 2: 2x + 3x + 4x + 6x = 15x = 360 → x = 24°।<br>चरण 3: सबसे बड़ा = 6 × 24 = 144°।<br>अतः उत्तर = <b>144°</b>"},
    {"q":"130° के संपूरक कोण का पूरक कोण कितना है?","o":["50°","140°","130°","40°"],"a":3,"e":"<b>हल:</b><br>चरण 1: 130° का संपूरक = 180 − 130 = 50°।<br>चरण 2: 50° का पूरक = 90 − 50 = 40°।<br>अतः उत्तर = <b>40°</b><br><b>ध्यान दें:</b> 50° केवल संपूरक है — दूसरा चरण न छोड़ें।"},
    {"q":"वह कोण जो अपने संपूरक कोण के बराबर हो, कितने अंश का होता है?","o":["45°","180°","90°","60°"],"a":2,"e":"<b>हल:</b><br>चरण 1: x = 180 − x।<br>चरण 2: 2x = 180 → x = 90°।<br>अतः उत्तर = <b>90°</b><br><b>ध्यान दें:</b> अपने पूरक के बराबर कोण 45° होता है — पूरक और संपूरक न मिलाएँ।"},
    {"q":"AB ∥ CD हैं तथा बिंदु E इन दोनों रेखाओं के बीच, A और C की ओर स्थित है। यदि ∠ABE = 40° और ∠CDE = 35° हो, तो ∠BED कितना है?","o":["75°","105°","5°","85°"],"a":0,"e":"<b>हल:</b><br>चरण 1: E से AB के समांतर एक रेखा EF खींचें (तब EF ∥ CD भी)।<br>चरण 2: AB ∥ EF → ∠BEF = ∠ABE = 40° (एकांतर कोण)।<br>चरण 3: CD ∥ EF → ∠DEF = ∠CDE = 35° (एकांतर कोण)।<br>चरण 4: ∠BED = 40° + 35° = 75°।<br>अतः उत्तर = <b>75°</b><br><b>शॉर्टकट:</b> \"Z/M आकृति\" नियम: बीच का कोण = दोनों बाहरी कोणों का योग।"},
    {"q":"दो समांतर रेखाओं को एक तिर्यक रेखा काटती है। तिर्यक रेखा के एक ही ओर के दोनों अंतः कोणों के समद्विभाजकों के बीच का कोण कितना होता है?","o":["45°","180°","60°","90°"],"a":3,"e":"<b>हल:</b><br>चरण 1: एक ही ओर के अंतः कोण x और y → x + y = 180°।<br>चरण 2: समद्विभाजक और तिर्यक रेखा से त्रिभुज बनता है जिसके दो कोण x/2 और y/2 हैं।<br>चरण 3: x/2 + y/2 = 90° → तीसरा कोण = 180 − 90 = 90°।<br>अतः उत्तर = <b>90°</b>"},
    {"q":"दो प्रतिच्छेदी रेखाओं से बने दो शीर्षाभिमुख कोणों के समद्विभाजकों के बीच का कोण कितना होता है?","o":["90°","180°","0°","45°"],"a":1,"e":"<b>हल:</b><br>चरण 1: शीर्षाभिमुख कोण x, x; उनके बीच का कोण 180° − x।<br>चरण 2: एक समद्विभाजक से दूसरे तक कोण = x/2 + (180 − x) + x/2।<br>चरण 3: = 180° → दोनों समद्विभाजक एक ही सरल रेखा में।<br>अतः उत्तर = <b>180°</b>"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. दो न्यून कोण आपस में संपूरक नहीं हो सकते।<br>2. दो अधिक कोण आपस में पूरक हो सकते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"<b>हल:</b><br>चरण 1: कथन 1: दो न्यून कोण (प्रत्येक 90° से कम) का योग 180° से कम → संपूरक नहीं हो सकते → सही।<br>चरण 2: कथन 2: दो अधिक कोण (प्रत्येक 90° से अधिक) का योग 180° से अधिक → योग 90° असंभव → गलत।<br>अतः उत्तर = <b>केवल 1</b>"},
    {"q":"एक दिन (24 घंटे) में घड़ी की घंटे और मिनट की सुइयाँ कितनी बार एक सरल रेखा में होती हैं (संपाती अथवा परस्पर विपरीत)?","o":["24","22","44","48"],"a":2,"e":"<b>हल:</b><br>चरण 1: 12 घंटे में सुइयाँ 11 बार संपाती (0°) होती हैं।<br>चरण 2: 12 घंटे में 11 बार विपरीत (180°) होती हैं।<br>चरण 3: 12 घंटे में 22 बार → 24 घंटे में 44 बार।<br>अतः उत्तर = <b>44</b><br><b>ध्यान दें:</b> 22 केवल 12 घंटे का उत्तर है।"},
    {"q":"123°45′30″ का संपूरक कोण क्या है?","o":["57°14′30″","56°15′30″","56°24′30″","56°14′30″"],"a":3,"e":"<b>हल:</b><br>चरण 1: संपूरक = 180° − 123°45′30″।<br>चरण 2: 180° = 179°59′60″ लिखें।<br>चरण 3: सेकंड: 60 − 30 = 30″; मिनट: 59 − 45 = 14′; अंश: 179 − 123 = 56°।<br>चरण 4: = 56°14′30″।<br>अतः उत्तर = <b>56°14′30″</b><br><b>ध्यान दें:</b> उधार लेना भूलने पर 57°14′30″ या 56°15′30″ आता है।"},
    {"q":"एक तल में 8 बिंदु हैं जिनमें से केवल 3 बिंदु संरेख हैं। इन बिंदुओं से कितने त्रिभुज बनाए जा सकते हैं?","o":["56","55","53","52"],"a":1,"e":"<b>हल:</b><br>चरण 1: कुल त्रिभुज (कोई संरेख न हो तो) = ⁸C₃ = 8 × 7 × 6/6 = 56।<br>चरण 2: 3 संरेख बिंदुओं का ³C₃ = 1 \"त्रिभुज\" वास्तव में नहीं बनता।<br>चरण 3: 56 − 1 = 55।<br>अतः उत्तर = <b>55</b><br><b>शॉर्टकट:</b> ⁿC₃ − ᵐC₃।"},
    {"q":"एक रेखा पर 5 भिन्न बिंदु स्थित हैं। इन बिंदुओं से कुल कितने रेखाखंड बनते हैं?","o":["5","10","4","20"],"a":1,"e":"<b>हल:</b><br>चरण 1: हर दो बिंदु एक रेखाखंड देते हैं।<br>चरण 2: ⁵C₂ = 5 × 4/2 = 10।<br>अतः उत्तर = <b>10</b><br><b>ध्यान दें:</b> 4 केवल आसन्न बिंदुओं के बीच के छोटे खंड हैं; AC, AD आदि भी रेखाखंड हैं।"},
    {"q":"दो रेखाएँ एक-दूसरे को काटती हैं। दो शीर्षाभिमुख कोणों का योग 100° है। शेष प्रत्येक कोण कितना है?","o":["50°","100°","80°","130°"],"a":3,"e":"<b>हल:</b><br>चरण 1: शीर्षाभिमुख कोण बराबर → प्रत्येक = 100/2 = 50°।<br>चरण 2: शेष प्रत्येक कोण, 50° के साथ रैखिक युग्म → 180 − 50 = 130°।<br>अतः उत्तर = <b>130°</b><br><b>ध्यान दें:</b> 50° दिए गए कोणों का माप है, शेष कोणों का नहीं।"},
    {"q":"अभिकथन (A): दो रेखाओं के प्रतिच्छेद से बने शीर्षाभिमुख कोण बराबर होते हैं।<br>कारण (R): दोनों शीर्षाभिमुख कोण, बीच वाले एक ही आसन्न कोण के साथ रैखिक युग्म बनाते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"<b>हल:</b><br>चरण 1: A: शीर्षाभिमुख कोण बराबर — सही।<br>चरण 2: R: ∠1 + ∠2 = 180° और ∠3 + ∠2 = 180° (दोनों रैखिक युग्म) — सही।<br>चरण 3: R से सीधे ∠1 = ∠3 निकलता है → R, A की सही व्याख्या है।<br>अतः उत्तर = <b>A और R दोनों सही हैं तथा R, A की सही व्याख्या है</b>"},
    {"q":"सूची-I (कोण) को सूची-II (कोण का प्रकार) से सुमेलित कीजिए —<br>(A) 90° (B) 180° (C) 270° (D) 360°<br>1. सरल (ऋजु) कोण 2. समकोण 3. संपूर्ण कोण 4. प्रतिवर्ती कोण","o":["A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-4, B-1, C-2, D-3"],"a":2,"e":"<b>हल:</b><br>चरण 1: (A) 90° = समकोण → 2।<br>चरण 2: (B) 180° = सरल कोण → 1।<br>चरण 3: (C) 270° (180° और 360° के बीच) = प्रतिवर्ती कोण → 4।<br>चरण 4: (D) 360° = संपूर्ण कोण → 3।<br>अतः उत्तर = <b>A-2, B-1, C-4, D-3</b>"},
    {"q":"एक समकोण के 3/5 भाग के बराबर कोण का पूरक कोण कितना है?","o":["36°","54°","126°","144°"],"a":0,"e":"<b>हल:</b><br>चरण 1: समकोण का 3/5 = 90 × 3/5 = 54°।<br>चरण 2: 54° का पूरक = 90 − 54 = 36°।<br>अतः उत्तर = <b>36°</b><br><b>ध्यान दें:</b> 54° स्वयं कोण है, उसका पूरक नहीं।"},
    {"q":"12:00 बजे से 12:30 बजे तक मिनट की सुई, घंटे की सुई की तुलना में कितने अंश अधिक घूमती है?","o":["180°","150°","175°","165°"],"a":3,"e":"<b>हल:</b><br>चरण 1: 30 मिनट में मिनट की सुई = 30 × 6 = 180°।<br>चरण 2: 30 मिनट में घंटे की सुई = 30 × 0.5 = 15°।<br>चरण 3: अंतर = 180 − 15 = 165°।<br>अतः उत्तर = <b>165°</b><br><b>शॉर्टकट:</b> सापेक्ष गति 5.5°/मिनट × 30 = 165°।"},
    {"q":"अभिकथन (A): 180° का कोण सरल (ऋजु) कोण कहलाता है।<br>कारण (R): सरल कोण की दोनों भुजाएँ (किरणें) एक ही दिशा में होती हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"<b>हल:</b><br>चरण 1: A: 180° का कोण सरल कोण कहलाता है — सही।<br>चरण 2: R: सरल कोण की भुजाएँ परस्पर विपरीत दिशाओं में होती हैं (तभी एक सीधी रेखा बनती है); एक ही दिशा में भुजाएँ तो शून्य कोण बनाती हैं — गलत।<br>अतः उत्तर = <b>A सही है, R गलत है</b>"},
    {"q":"A, B, C संरेख बिंदु हैं। AB = 5 सेमी, BC = 3 सेमी और AC = 8 सेमी है। कौन-सा बिंदु शेष दोनों के बीच स्थित है?","o":["A","B","C","निश्चित नहीं किया जा सकता"],"a":1,"e":"<b>हल:</b><br>चरण 1: संरेख बिंदुओं में बीच वाले बिंदु के लिए: दोनों छोटे भागों का योग = पूरी दूरी।<br>चरण 2: AB + BC = 5 + 3 = 8 = AC।<br>चरण 3: अतः B, A और C के बीच है।<br>अतः उत्तर = <b>B</b>"},
    {"q":"रेखाखंड AB = 12 सेमी है। C, AB का मध्य बिंदु है और D, CB का मध्य बिंदु है। AD की लंबाई कितनी है?","o":["6 सेमी","3 सेमी","8 सेमी","9 सेमी"],"a":3,"e":"<b>हल:</b><br>चरण 1: C मध्य बिंदु → AC = CB = 12/2 = 6 सेमी।<br>चरण 2: D, CB का मध्य बिंदु → CD = 6/2 = 3 सेमी।<br>चरण 3: AD = AC + CD = 6 + 3 = 9 सेमी।<br>अतः उत्तर = <b>9 सेमी</b>"},
    {"q":"दो समांतर रेखाओं को एक तिर्यक रेखा काटती है। तिर्यक रेखा के एक ही ओर के दो बाह्य कोण (2x + 20)° और (x + 10)° हैं। बड़ा कोण कितना है?","o":["120°","60°","100°","110°"],"a":0,"e":"<b>हल:</b><br>चरण 1: एक ही ओर के बाह्य कोण संपूरक → योग 180°।<br>चरण 2: (2x + 20) + (x + 10) = 180 → 3x + 30 = 180 → x = 50।<br>चरण 3: कोण: 2 × 50 + 20 = 120°, 50 + 10 = 60°।<br>अतः उत्तर = <b>120°</b>"},
    {"q":"यदि रेखा l ∥ m और m ∥ n हो (सभी एक ही तल में), तो —","o":["l ⊥ n","l और n प्रतिच्छेदी हैं","l ∥ n","कुछ निश्चित नहीं"],"a":2,"e":"<b>हल:</b><br>चरण 1: एक ही रेखा (m) के समांतर दो रेखाएँ परस्पर समांतर होती हैं।<br>चरण 2: अतः l ∥ n।<br>अतः उत्तर = <b>l ∥ n</b>"},
    {"q":"एक ही तल में किसी एक रेखा पर लंब दो भिन्न रेखाएँ परस्पर —","o":["लंब होती हैं","समांतर होती हैं","संपाती होती हैं","45° पर प्रतिच्छेद करती हैं"],"a":1,"e":"<b>हल:</b><br>चरण 1: दोनों रेखाएँ उस रेखा (तिर्यक) से 90° बनाती हैं।<br>चरण 2: ये 90° के कोण संगत कोण हैं और बराबर हैं।<br>चरण 3: संगत कोण बराबर → रेखाएँ समांतर।<br>अतः उत्तर = <b>समांतर होती हैं</b>"},
    {"q":"एक पूर्ण चक्कर के 3/5 भाग में कितने अंश होते हैं?","o":["180°","240°","216°","108°"],"a":2,"e":"<b>हल:</b><br>चरण 1: पूर्ण चक्कर = 360°।<br>चरण 2: 360 × 3/5 = 72 × 3 = 216°।<br>अतः उत्तर = <b>216°</b>"},
    {"q":"एक व्यक्ति उत्तर दिशा की ओर मुँह करके खड़ा है। वह दक्षिणावर्त (घड़ी की दिशा में) 135° घूम जाता है। अब उसका मुँह किस दिशा में है?","o":["दक्षिण-पश्चिम","उत्तर-पूर्व","दक्षिण","दक्षिण-पूर्व"],"a":3,"e":"<b>हल:</b><br>चरण 1: उत्तर से दक्षिणावर्त: 90° → पूर्व, 180° → दक्षिण।<br>चरण 2: 135° = 90° + 45° → पूर्व और दक्षिण के ठीक बीच।<br>चरण 3: = दक्षिण-पूर्व।<br>अतः उत्तर = <b>दक्षिण-पूर्व</b><br><b>ध्यान दें:</b> वामावर्त घूमने पर दक्षिण-पश्चिम आता — दिशा (घड़ी की दिशा) ध्यान से पढ़ें।"},
    {"q":"एक व्यक्ति पूर्व की ओर मुँह करके खड़ा है। वह वामावर्त (घड़ी की विपरीत दिशा में) 270° घूम जाता है। अब उसका मुँह किस दिशा में है?","o":["उत्तर","दक्षिण","पश्चिम","पूर्व"],"a":1,"e":"<b>हल:</b><br>चरण 1: पूर्व से वामावर्त 90° → उत्तर।<br>चरण 2: 180° → पश्चिम।<br>चरण 3: 270° → दक्षिण।<br>अतः उत्तर = <b>दक्षिण</b><br><b>शॉर्टकट:</b> वामावर्त 270° = दक्षिणावर्त 90° → पूर्व से दक्षिणावर्त 90° = दक्षिण।"},
    {"q":"दक्षिण-पश्चिम और उत्तर दिशाओं के बीच का (छोटा) कोण कितना है?","o":["135°","45°","225°","90°"],"a":0,"e":"<b>हल:</b><br>चरण 1: उत्तर से दक्षिण तक = 180°।<br>चरण 2: दक्षिण से दक्षिण-पश्चिम = 45°।<br>चरण 3: उत्तर से दक्षिण-पश्चिम (पश्चिम की ओर से): 90° (पश्चिम) + 45° = 135°।<br>अतः उत्तर = <b>135°</b><br><b>ध्यान दें:</b> 225° बड़ा (प्रतिवर्ती) कोण है।"},
    {"q":"1.25 समकोण कितने अंश के बराबर है?","o":["125°","112.5°","100°","115°"],"a":1,"e":"<b>हल:</b><br>चरण 1: 1 समकोण = 90°।<br>चरण 2: 1.25 × 90 = 112.5°।<br>अतः उत्तर = <b>112.5°</b>"},
    {"q":"∠A और ∠B संपूरक हैं तथा ∠B और ∠C पूरक हैं। यदि ∠A = 130° हो तो ∠C कितना है?","o":["50°","130°","140°","40°"],"a":3,"e":"<b>हल:</b><br>चरण 1: ∠A + ∠B = 180° → ∠B = 180 − 130 = 50°।<br>चरण 2: ∠B + ∠C = 90° → ∠C = 90 − 50 = 40°।<br>अतः उत्तर = <b>40°</b><br><b>ध्यान दें:</b> 50° ∠B है, ∠C नहीं।"},
    {"q":"एक तल में 4 समांतर रेखाएँ, 3 अन्य समांतर रेखाओं को काटती हैं। इनसे कुल कितने समांतर चतुर्भुज बनते हैं?","o":["12","7","18","24"],"a":2,"e":"<b>हल:</b><br>चरण 1: समांतर चतुर्भुज के लिए एक समूह की 2 रेखाएँ और दूसरे समूह की 2 रेखाएँ चाहिए।<br>चरण 2: ⁴C₂ = 6, ³C₂ = 3।<br>चरण 3: कुल = 6 × 3 = 18।<br>अतः उत्तर = <b>18</b><br><b>ध्यान दें:</b> 12 (= 4 × 3) प्रतिच्छेद बिंदुओं की संख्या है।"},
    {"q":"एक तल में 4 रेखाएँ हैं जिनमें केवल दो परस्पर समांतर हैं और कोई तीन संगामी नहीं हैं। प्रतिच्छेद बिंदुओं की संख्या कितनी है?","o":["5","6","4","3"],"a":0,"e":"<b>हल:</b><br>चरण 1: यदि कोई दो समांतर न होतीं: ⁴C₂ = 6 बिंदु।<br>चरण 2: समांतर युग्म आपस में नहीं कटता → 1 बिंदु कम।<br>चरण 3: 6 − 1 = 5।<br>अतः उत्तर = <b>5</b>"},
    {"q":"किरण AB और किरण BA के संबंध में सही कथन कौन-सा है?","o":["दोनों एक ही किरण हैं","दोनों की लंबाई बराबर है","दोनों एक ही प्रारंभिक बिंदु वाली विपरीत किरणें हैं","दोनों भिन्न हैं क्योंकि इनके प्रारंभिक बिंदु अलग-अलग हैं"],"a":3,"e":"<b>हल:</b><br>चरण 1: किरण AB: प्रारंभिक बिंदु A, दिशा B की ओर।<br>चरण 2: किरण BA: प्रारंभिक बिंदु B, दिशा A की ओर।<br>चरण 3: प्रारंभिक बिंदु और दिशा दोनों अलग → भिन्न किरणें; किरण की लंबाई अनंत होती है, मापी नहीं जा सकती।<br>अतः उत्तर = <b>दोनों भिन्न हैं क्योंकि इनके प्रारंभिक बिंदु अलग-अलग हैं</b><br><b>ध्यान दें:</b> \"विपरीत किरणें\" वे होती हैं जिनका प्रारंभिक बिंदु एक ही हो।"},
    {"q":"∠AOB और ∠BOC आसन्न कोण हैं तथा ∠AOC = 90° है। यदि ∠AOB = 2∠BOC + 15° हो, तो ∠AOB कितना है?","o":["65°","25°","55°","75°"],"a":0,"e":"<b>हल:</b><br>चरण 1: माना ∠BOC = x → ∠AOB = 2x + 15।<br>चरण 2: ∠AOB + ∠BOC = ∠AOC → (2x + 15) + x = 90।<br>चरण 3: 3x = 75 → x = 25° → ∠AOB = 2 × 25 + 15 = 65°।<br>अतः उत्तर = <b>65°</b><br><b>ध्यान दें:</b> 25° ∠BOC है।"},
    {"q":"पृथ्वी अपने अक्ष पर 1 घंटे में कितने अंश घूमती है?","o":["30°","15°","1°","24°"],"a":1,"e":"<b>हल:</b><br>चरण 1: पृथ्वी 24 घंटे में 360° घूमती है।<br>चरण 2: 1 घंटे में = 360 ÷ 24 = 15°।<br>अतः उत्तर = <b>15°</b><br><b>शॉर्टकट:</b> 1° घूमने में 4 मिनट लगते हैं (देशांतर-समय संबंध)।"},
    {"q":"एक वृत्त पर 7 बिंदु स्थित हैं। इन्हें मिलाकर कितनी जीवाएँ खींची जा सकती हैं?","o":["14","42","21","35"],"a":2,"e":"<b>हल:</b><br>चरण 1: वृत्त पर कोई तीन बिंदु संरेख नहीं होते।<br>चरण 2: हर दो बिंदु एक जीवा → ⁷C₂ = 7 × 6/2 = 21।<br>अतः उत्तर = <b>21</b><br><b>ध्यान दें:</b> 42 (= 7 × 6) में हर जीवा दो बार गिनी जाती है।"}
  ]
});
